// Some portions generated by Codex
package org.eclipse.rdf4j.sail.base;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Query;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

class SlowQueryBlankNodeDatasetTest {
	@Test
	void blankNodeRuntimeSelectorsRemainVisibleWithoutBecomingSourceFromClauses() {
		var vf = SimpleValueFactory.getInstance();
		var dataset = new SimpleDataset();
		dataset.addDefaultGraph(vf.createBNode("default"));
		dataset.addDefaultGraph(vf.createIRI("https://example.invalid/source"));
		dataset.addNamedGraph(vf.createBNode("named"));
		dataset.setExplicitReadDataset(true);
		String text = "SELECT ?s WHERE { ?s <urn:p> ?o }";
		var expression = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, text, null).getTupleExpr();
		var info = new SlowQueryLogInfo("MemoryStore", 1L, 0L, Query.QueryType.TUPLE, text, expression, expression,
				dataset, Set.of());
		String rendered = new SlowQueryLogFormatter().formatExecution(info, 2000L);
		assertFalse(rendered.contains("Renderer throwable:"), rendered);
		assertFalse(rendered.contains("<unavailable>"), rendered);
		assertTrue(rendered.contains("<_:default>"), rendered);
		assertTrue(rendered.contains("<_:named>"), rendered);
		assertTrue(rendered.contains("https://example.invalid/source"), rendered);
		assertFalse(rendered.contains("FROM <"),
				"a mixed runtime dataset must not be reduced to partial source clauses");
	}
}
